{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_2d1f9762553c4848865081535a20c7f4.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @* Error Display *@
    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @* Step Content *@
    <div class="step-content">
        @switch (CurrentStep)
        {
            case 0:
                @RenderPersonalInfo();
                break;
            case 1:
                @RenderWorkHistory();
                break;
            case 2:
                @RenderReferences();
                break;
            case 3:
                @RenderCoverLetter();
                break;
            case 4:
                @RenderReviewSubmit();
                break;
        }
    </div>
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private string ErrorMessage { get; set; } = "";
    private bool IsSubmitting { get; set; }
    private int? SubmittedApplicationId { get; set; }

    // Form state
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    private string CoverLetter { get; set; } = "";
    private const int CoverLetterMaxLength = 2000;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private void GoToStep(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            CurrentStep = stepIndex;
            ErrorMessage = "";
        }
    }

    private async Task NextStep()
    {
        ErrorMessage = "";

        if (!ValidateCurrentStep())
            return;

        if (CurrentStep == 0)
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        CurrentStep++;
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ErrorMessage = "";
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName))
                { ErrorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(Email))
                { ErrorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(Phone))
                { ErrorMessage = "Phone is required."; return false; }
                if (string.IsNullOrWhiteSpace(Address))
                { ErrorMessage = "Address is required."; return false; }
                return true;

            case 1:
                foreach (var entry in WorkEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                    { ErrorMessage = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                    { ErrorMessage = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                    { ErrorMessage = "Start date is required for all entries."; return false; }
                }
                return true;

            case 2:
                foreach (var r in References)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                    { ErrorMessage = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Relationship))
                    { ErrorMessage = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                    { ErrorMessage = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Phone))
                    { ErrorMessage = "Phone is required for all references."; return false; }
                }
                return true;

            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetter))
                { ErrorMessage = "Cover letter is required."; return false; }
                return true;

            default:
                return true;
        }
    }

    private async Task SubmitApplication()
    {
        IsSubmitting = true;
        ErrorMessage = "";

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workEntries = WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")).ToList();
            var work = new WorkHistory(workEntries);
            var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, CoverLetter);

            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    private void AddWorkEntry()
    {
        WorkEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(WorkEntryModel entry)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.Remove(entry);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(ReferenceModel reference)
    {
        if (References.Count > 2)
            References.Remove(reference);
    }

    // View models for mutable form state
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    // Render fragments
    private RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="FullName" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="Email" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="Phone" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <input id="address" type="text" @bind="Address" placeholder="Enter your address" />
        </div>
        <div class="button-row">
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderWorkHistory() => __builder =>
    {
        <h2>Work History</h2>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var entry = WorkEntries[i];
            <div class="work-entry-card">
                <div class="entry-header">
                    <h3>Position @(i + 1)</h3>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(entry)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" @bind="entry.Company" placeholder="Company name" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" @bind="entry.Title" placeholder="Job title" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="entry.StartDate" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                        <label class="checkbox-label">
                            <input type="checkbox" @bind="entry.IsCurrent" /> Currently working here
                        </label>
                    </div>
                </div>
                <div class="form-group">
                    <label>Description</label>
                    <textarea @bind="entry.Description" placeholder="Describe your responsibilities..." rows="3"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="button-row">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderReferences() => __builder =>
    {
        <h2>References</h2>
        @for (int i = 0; i < References.Count; i++)
        {
            var reference = References[i];
            <div class="reference-card">
                <div class="entry-header">
                    <h3>Reference @(i + 1)</h3>
                    @if (References.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(reference)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" @bind="reference.Name" placeholder="Reference name" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" @bind="reference.Relationship" placeholder="e.g., Former Manager" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="reference.Email" placeholder="Email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="reference.Phone" placeholder="Phone" />
                    </div>
                </div>
            </div>
        }
        @if (References.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="button-row">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderCoverLetter() => __builder =>
    {
        <h2>Cover Letter</h2>
        <div class="form-group">
            <label for="coverLetter">Write your cover letter *</label>
            <textarea id="coverLetter" @bind="CoverLetter" @bind:event="oninput" placeholder="Tell us why you're a great fit..."
                rows="12" maxlength="@CoverLetterMaxLength"></textarea>
            <div class="char-count @(CoverLetter.Length > CoverLetterMaxLength ? "over-limit" : "")">
                @CoverLetter.Length / @CoverLetterMaxLength characters
            </div>
        </div>
        <div class="button-row">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderReviewSubmit() => __builder =>
    {
        @if (SubmittedApplicationId.HasValue)
        {
            <div class="confirmation">
                <div class="confirmation-icon">&#10003;</div>
                <h2>Application Submitted!</h2>
                <p>Your application has been successfully submitted.</p>
                <p class="application-id">Application ID: <strong>@SubmittedApplicationId.Value</strong></p>
            </div>
        }
        else
        {
            <h2>Review & Submit</h2>

            <div class="review-section">
                <div class="review-header">
                    <h3>Personal Information</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                </div>
                <dl>
                    <dt>Full Name</dt><dd>@FullName</dd>
                    <dt>Email</dt><dd>@Email</dd>
                    <dt>Phone</dt><dd>@Phone</dd>
                    <dt>Address</dt><dd>@Address</dd>
                </dl>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Work History</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>References</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <span>@r.Email | @r.Phone</span>
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Cover Letter</h3>
                    <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <p class="cover-letter-preview">@CoverLetter</p>
            </div>

            <div class="button-row">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsSubmitting">
                    @(IsSubmitting ? "Submitting..." : "Submit Application")
                </button>
            </div>
        }
    };
}
