toolArgs.file_text:
.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.72rem;
    color: #666;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    min-width: 20px;
    max-width: 60px;
    margin-top: -1.2rem;
}

.step-connector.completed {
    background: #2ecc71;
}

.checkmark {
    font-size: 1rem;
}

/* Form Styles */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
    font-size: 0.85rem;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Cards for entries */
.work-entry-card,
.reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

/* Buttons */
.button-row {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.btn-next,
.btn-back,
.btn-submit,
.btn-add,
.btn-remove,
.btn-edit {
    padding: 0.6rem 1.4rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s, opacity 0.2s;
}

.btn-next {
    background: #4361ee;
    color: #fff;
    margin-left: auto;
}

.btn-next:hover {
    background: #3651d4;
}

.btn-back {
    background: #e0e0e0;
    color: #333;
}

.btn-back:hover {
    background: #d0d0d0;
}

.btn-submit {
    background: #2ecc71;
    color: #fff;
    font-size: 1rem;
    padding: 0.75rem 2rem;
}

.btn-submit:hover:not(:disabled) {
    background: #27ae60;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background: #f0f0f0;
    color: #4361ee;
    border: 1px dashed #4361ee;
    width: 100%;
    margin-bottom: 1rem;
}

.btn-add:hover {
    background: #e8eeff;
}

.btn-remove {
    background: #fee;
    color: #e74c3c;
    font-size: 0.8rem;
    padding: 0.4rem 0.8rem;
}

.btn-remove:hover {
    background: #fdd;
}

.btn-edit {
    background: transparent;
    color: #4361ee;
    font-size: 0.85rem;
    padding: 0.3rem 0.6rem;
    text-decoration: underline;
}

.btn-edit:hover {
    color: #3651d4;
}

/* Error */
.error-message {
    background: #fee;
    border: 1px solid #e74c3c;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.3rem;
}

.char-count.over-limit {
    color: #e74c3c;
    font-weight: 600;
}

/* Review Section */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
    font-size: 0.85rem;
}

.review-section dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
    font-size: 0.9rem;
}

.review-entry:last-child {
    border-bottom: none;
}

.review-entry p {
    margin: 0.3rem 0 0;
    color: #555;
    font-size: 0.85rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #333;
    margin: 0;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: #2ecc71;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

.confirmation h2 {
    color: #2ecc71;
}

.application-id {
    font-size: 1.1rem;
    margin-top: 1rem;
}

